#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

if [[ "$(uname)" == "Darwin" ]]; then
  CONFIG_DIR="${SKIT_CONFIG_DIR:-$HOME/Library/Application Support/social-kit}"
else
  CONFIG_DIR="${SKIT_CONFIG_DIR:-${XDG_CONFIG_HOME:-$HOME/.config}/social-kit}"
fi
mkdir -p "$CONFIG_DIR" && chmod 700 "$CONFIG_DIR"
ENV_FILE="$CONFIG_DIR/dev-setup.env"
REDIRECT="http://localhost:8765/callback"

banner "social-kit: your Meta app for Pages, Instagram and Threads"

stage "Create the app"
say "A new Business app in the Language Ranch portfolio, the one skit will use day to day (separate from Language Ranch Ops)."
open_url "https://developers.facebook.com/apps/creation/"
step "App details: name it  social-kit  (no Meta, Facebook, Instagram or Threads in the name). Contact email: yours."
step "Use cases: tick  Manage everything on your Page,  Manage messaging and content on Instagram,"
step "           Access the Threads API,  and  Engage with customers on Messenger from Meta.  Do NOT tick 'Authenticate and request data from users with Facebook Login'."
warn "If one is greyed out, note which one, finish with the others, and tell Claude."
step "Business: connect the  Language Ranch  portfolio (the system-user check needs it)."
step "Requirements / Overview: click through, then Go to dashboard. Leave the app unpublished (Development)."
ask DEV_GREYED_OUT "Any use case greyed out? (none, or its name):"
write_env DEV_GREYED_OUT "$DEV_GREYED_OUT"

stage "App credentials"
say "The Meta app id and secret, then the Threads app id and secret (a second pair inside the same app)."
step "Dashboard → App settings → Basic. Copy App ID; click Show on App secret and copy it."
ask SKIT_APP_ID "App ID:"
write_env SKIT_APP_ID "$SKIT_APP_ID"
ask_secret SKIT_APP_SECRET "App secret (hidden):"
write_env SKIT_APP_SECRET "$SKIT_APP_SECRET"
step "Threads App ID and Threads App secret: on the same Basic page, or under"
step "Use cases → Access the Threads API → Customize → Settings."
ask SKIT_THREADS_APP_ID "Threads App ID:"
write_env SKIT_THREADS_APP_ID "$SKIT_THREADS_APP_ID"
ask_secret SKIT_THREADS_APP_SECRET "Threads App secret (hidden):"
write_env SKIT_THREADS_APP_SECRET "$SKIT_THREADS_APP_SECRET"

stage "Security setting"
open_url "https://developers.facebook.com/apps/$SKIT_APP_ID/settings/advanced/"
step "Security section: make sure  Native or Desktop App?  is OFF (it blocks app-token calls such as debug_token)."
step "Leave  Require App Secret  as it is; the test script always sends appsecret_proof."
pause "Done?"

stage "Pages permissions and Facebook redirect"
open_url "https://developers.facebook.com/apps/$SKIT_APP_ID/use_cases/"
step "Manage everything on your Page → Customize → Permissions. Click Add on each that is offered:"
note "    pages_show_list  pages_read_engagement  pages_manage_posts  pages_manage_engagement"
note "    pages_read_user_content  pages_manage_metadata  pages_messaging  read_insights  business_management"
step "Facebook Login for Business → Settings → Valid OAuth Redirect URIs: try adding"
note "    $REDIRECT"
note "    then Save. Meta refused localhost on Language Ranch Ops; development mode accepted it anyway."
ask DEV_FB_LOCALHOST_SAVED "Did the localhost redirect save? (y/n):"
write_env DEV_FB_LOCALHOST_SAVED "$DEV_FB_LOCALHOST_SAVED"

stage "Instagram permissions"
open_url "https://developers.facebook.com/apps/$SKIT_APP_ID/use_cases/"
step "Manage messaging and content on Instagram → Customize → choose  API setup with Facebook login."
step "Click  Add all required permissions  and  Add required messaging permissions."
step "Also click Add on any of these still listed:  instagram_manage_comments  instagram_manage_insights  instagram_manage_messages"
step "Engage with customers on Messenger → Customize → Permissions: Add every permission offered (pages_messaging at least)."
warn "Skip any 'Business verification' or 'App Review' prompt; development mode doesn't need either."
pause "Done?"

stage "Threads permissions, redirect and tester"
open_url "https://developers.facebook.com/apps/$SKIT_APP_ID/use_cases/"
step "Access the Threads API → Customize → Permissions: Add every optional threads_* permission."
step "Settings: Redirect Callback URLs: add  $REDIRECT"
step "  Uninstall and Delete callback URLs, if Save insists: https://github.com/eukosh/social-kit"
ask DEV_THREADS_LOCALHOST_SAVED "Did the Threads localhost redirect save? (y/n, or the error text):"
write_env DEV_THREADS_LOCALHOST_SAVED "$DEV_THREADS_LOCALHOST_SAVED"
step "App roles → Roles → Add People → Threads Tester → the Threads account to test with."
note "    If the dashboard says roles are managed in the business portfolio, add it from there."
ask DEV_THREADS_TESTER "Threads username you invited (public):"
write_env DEV_THREADS_TESTER "$DEV_THREADS_TESTER"
open_url "https://www.threads.com/settings/account"
step "Signed in as @$DEV_THREADS_TESTER on Threads: Account → Website permissions → Invites → Accept."
pause "Accepted?"

stage "System user for the headless check"
say "A non-expiring system-user token on this app, to see which scopes Meta offers and what it reaches."
open_url "https://business.facebook.com/settings/system-users"
step "Add a system user  skit  (role Employee). If the portfolio refuses another one, use the existing"
step "  ads-cli: generating a token for a different app leaves the Ads CLI's token untouched."
step "Assign assets: Page Language Ranch and Instagram language_ranch, every partial permission, no Full control;"
step "  app social-kit (Develop / Manage app)."
step "Generate token → app social-kit → expiration  Never  → tick every permission already on the app; untick any the dialog lists as not added to your app (Continue would add them)."
ask DEV_SYSTEM_USER "System user used (skit or ads-cli):"
write_env DEV_SYSTEM_USER "$DEV_SYSTEM_USER"
ask_secret DEV_SYSTEM_USER_TOKEN "Paste the token (hidden; Meta shows it once):"
write_env DEV_SYSTEM_USER_TOKEN "$DEV_SYSTEM_USER_TOKEN"

stage "Write app.json"
say "Saving the app credentials in the layout decided for social-kit."
SKIT_APP_ID="$SKIT_APP_ID" SKIT_APP_SECRET="$SKIT_APP_SECRET" \
SKIT_THREADS_APP_ID="$SKIT_THREADS_APP_ID" SKIT_THREADS_APP_SECRET="$SKIT_THREADS_APP_SECRET" \
python3 - "$CONFIG_DIR/app.json" <<'PY'
import json, os, sys, tempfile
path = sys.argv[1]
data = {k: os.environ[f"SKIT_{k.upper()}"] for k in ("app_id", "app_secret", "threads_app_id", "threads_app_secret")}
fd, tmp = tempfile.mkstemp(dir=os.path.dirname(path))
with os.fdopen(fd, "w") as f:
    json.dump(data, f, indent=2)
os.chmod(tmp, 0o600)
os.replace(tmp, path)
PY
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$CONFIG_DIR/app.json"
note "Next: tell Claude the wizard is done. The OAuth logins come next."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
